"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";

interface Event {
  id: string;
  userId: string;
  title: string;
  description?: string;
  startDatetime: string;
  endDatetime: string;
}

export default function CalendarPage() {
  const { data: session } = useSession();
  const [events, setEvents] = useState<Event[]>([]);
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const [currentMonth, setCurrentMonth] = useState(new Date());

  const weekDays = ["Pzt","Sal","Çar","Per","Cum","Cmt","Paz"];

  useEffect(() => {
    async function fetchEvents() {
      const res = await fetch("/api/calendar");
      const data = await res.json();
      setEvents(data);
    }
    fetchEvents();
  }, []);

  function startOfMonth(date: Date) {
    return new Date(date.getFullYear(), date.getMonth(), 1);
  }

  function endOfMonth(date: Date) {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0);
  }

  function prevMonth() {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  }

  function nextMonth() {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));
  }

  function getDaysInMonth(date: Date) {
    const start = startOfMonth(date);
    const end = endOfMonth(date);
    const days: Date[] = [];
    for(let d = start.getDate(); d <= end.getDate(); d++) {
      days.push(new Date(date.getFullYear(), date.getMonth(), d));
    }
    return days;
  }

  async function handleAddEvent(e: React.FormEvent) {
    e.preventDefault();
    if (!session?.user?.id) return;

    const start = new Date(selectedDate);
    const end = new Date(selectedDate);
    end.setHours(end.getHours() + 1);

    const res = await fetch("/api/calendar", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        userId: session.user.id,
        title,
        description,
        startDatetime: start.toISOString(),
        endDatetime: end.toISOString(),
      }),
    });

    const newEvent = await res.json();
    setEvents([...events, newEvent]);
    setTitle("");
    setDescription("");
    setModalOpen(false);
  }

  const days = getDaysInMonth(currentMonth);
  const firstDayOfWeek = days[0].getDay() === 0 ? 6 : days[0].getDay() - 1; // Pzt=0

  return (
    <div className="p-6 min-h-screen bg-gray-50 relative">
      {/* Başlık ve buton */}
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-4">
          <button onClick={prevMonth} className="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300">&lt;</button>
          <h1 className="text-2xl font-bold">
            {currentMonth.toLocaleString("tr-TR", { month: "long" })} {currentMonth.getFullYear()}
          </h1>
          <button onClick={nextMonth} className="px-3 py-1 bg-gray-200 rounded hover:bg-gray-300">&gt;</button>
        </div>
        <button
          className="bg-gray-900 text-white px-4 py-2 rounded hover:bg-gray-800 shadow"
          onClick={() => setModalOpen(true)}
        >
          + Etkinlik Ekle
        </button>
      </div>

      {/* Haftanın günleri */}
      <div className="grid grid-cols-7 text-center font-semibold mb-2">
        {weekDays.map(d => <div key={d}>{d}</div>)}
      </div>

      {/* Takvim günleri */}
      <div className="grid grid-cols-7 gap-3">
        {/* Boşluklar */}
        {Array.from({length: firstDayOfWeek}).map((_, i) => <div key={`blank-${i}`} />)}

        {days.map(day => {
          const dayEvents = events.filter(ev =>
            new Date(ev.startDatetime).toDateString() === day.toDateString()
          );

          return (
            <div key={day.toISOString()} className="border rounded-lg min-h-80px p-2 flex flex-col bg-white shadow-sm">
              <div className="font-semibold mb-1">{day.getDate()}</div>
              {dayEvents.map(ev => (
                <div key={ev.id} className="bg-gray-200 rounded px-1 my-1 text-xs truncate">
                  {ev.title}
                </div>
              ))}
            </div>
          )
        })}
      </div>

      {/* Modal */}
      {modalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-40 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-xl shadow-xl w-96">
            <h2 className="text-xl font-semibold mb-4">Yeni Etkinlik Ekle</h2>
            <form onSubmit={handleAddEvent} className="space-y-4">
              <label className="block text-sm font-medium">Tarih:</label>
              <input
                type="date"
                className="w-full p-2 border rounded"
                value={selectedDate.toISOString().split("T")[0]}
                onChange={(e) => setSelectedDate(new Date(e.target.value))}
                required
              />

              <input
                type="text"
                placeholder="Başlık"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                className="w-full p-2 border rounded"
                required
              />
              <input
                type="text"
                placeholder="Açıklama"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full p-2 border rounded"
              />

              <div className="flex justify-end gap-2">
                <button
                  type="button"
                  className="px-4 py-2 border rounded"
                  onClick={() => setModalOpen(false)}
                >
                  İptal
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-gray-900 text-white rounded hover:bg-gray-800"
                >
                  Kaydet
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}